import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.map.js";
/* eslint-disable */
import { API, graphqlOperation } from "aws-amplify";
import { genrate_project_cost_graph } from "@/graphql/queries.js";
import ColoumnChart from "@/components/Graph/ColoumnChart.vue";
import SnackBar from "@/components/SnackBar.vue";
export default {
  components: {
    ColoumnChart,
    SnackBar
  },
  data() {
    return {
      formattedmonth: "",
      formattedyear: "",
      expenseTotal: "0",
      vendorTotal: "0",
      SnackBarComponent: {},
      sectionValue: [],
      expsenseValue: [],
      monthdailog: false,
      fixed: true,
      date1: ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"][Number(new Date().toISOString().split("T")[0].split("-")[1]) - 1] + " " + new Date().toISOString().split("T")[0].split("-")[0],
      date: new Date().toISOString().substr(0, 7),
      updatekey: 0,
      updateExpensekey: 0
    };
  },
  watch: {
    date(val) {
      this.date1 = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"][Number(val.split("-")[1]) - 1] + " " + val.split("-")[0];
    }
  },
  mounted() {
    this.get_next();
  },
  methods: {
    fecth_date() {
      const [month, year] = this.date1.split(" ");
      const monthMap = {
        January: "01",
        February: "02",
        March: "03",
        April: "04",
        May: "05",
        June: "06",
        July: "07",
        August: "08",
        September: "09",
        October: "10",
        November: "11",
        December: "12"
      };
      this.formattedmonth = `${monthMap[month]}`;
      this.formattedyear = `${year}`;
      this.formattedmonth = parseInt(this.formattedmonth, 10);
      this.formattedyear = parseInt(this.formattedyear, 10);
    },
    async get_next() {
      await this.fecth_date();
      let projectDetails = JSON.parse(localStorage.getItem("projectInfo"));
      try {
        let result = await API.graphql(graphqlOperation(genrate_project_cost_graph, {
          input: {
            //   year: this.formattedyear,
            //   month: this.formattedmonth,
            //   action_type: "GROUP",
            project_id: projectDetails.project_id
          }
        }));
        let resultdata = JSON.parse(result.data.genrate_project_cost_graph);
        if (resultdata.Status == "SUCCESS") {
          let response = resultdata.data;
          this.expenseTotal = resultdata.expense_total;
          this.vendorTotal = resultdata.vendor_total;
          // console.log(resultdata);
          if (response.expense) {
            let combined = response.expense.x.map((key, index) => ({
              key: key,
              value: parseInt(response.expense.y[index], 10)
            }));
            combined.sort((a, b) => b.value - a.value);
            response.x = combined.map(item => item.key);
            response.y = combined.map(item => item.value.toString());
            this.expsenseValue = [];
            this.updatekey++;
            this.updateExpensekey++;
            this.expsenseValue.push(response);
          }
          if (response.vendor) {
            let combined = response.vendor.x.map((key, index) => ({
              key: key,
              value: parseInt(response.vendor.y[index], 10)
            }));
            combined.sort((a, b) => b.value - a.value);
            response.x = combined.map(item => item.key);
            response.y = combined.map(item => item.value.toString());
            this.sectionValue = [];
            this.updatekey++;
            this.updateExpensekey++;
            this.sectionValue.push(response);
          }
        } else {
          this.sectionValue = [];
          this.expsenseValue = [];
          this.updatekey++;
          this.updateExpensekey++;
        }
      } catch (error) {
        this.sectionValue = [];
        this.updatekey++;
        this.updateExpensekey++;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    }
  }
};
